import java.util.*;

public class Main {
    static final int MOD = 1_000_000_007;
    static int N, A, B, C;
    static Long[][][][][] dp;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        A = sc.nextInt();
        B = sc.nextInt();
        C = sc.nextInt();
        sc.close();

        dp = new Long[N + 1][A + 1][B + 1][C + 1][8];
        long result = solve(0, 0, 0, 0, 0);
        System.out.println(result);
    }

    // openMask: bitmask of up to 3 pending numbers, each bit indicates if a number with that offset is open
    static long solve(int pos, int a, int b, int c, int openMask) {
        if (pos == N) {
            return (openMask == 0 && a == A && b == B && c == C) ? 1 : 0;
        }
        if (a > A || b > B || c > C) return 0;
        if (dp[pos][a][b][c][openMask] != null)
            return dp[pos][a][b][c][openMask];

        long res = 0;
        // Current smallest unmatched number is at position pos*2 + 1 = 2*pos+1
        int cur = 2 * pos + 1;

        // Option: pair cur with cur+1 (diff=1)
        if ((openMask & 1) == 0) { // no one waiting for diff 1 from before
            res += solve(pos + 1, a + 1, b, c, openMask >> 1);
        } else {
            // match with waiting number
            res += solve(pos + 1, a + 1, b, c, (openMask ^ 1) >> 1);
        }

        // Option: pair cur with cur+2 (diff=2)
        if ((openMask & 2) == 0) {
            res += solve(pos + 1, a, b + 1, c, (openMask >> 1) | 1);
        } else {
            res += solve(pos + 1, a, b + 1, c, ((openMask ^ 2) >> 1) | 1);
        }

        // Option: pair cur with cur+3 (diff=3)
        if ((openMask & 4) == 0) {
            res += solve(pos + 1, a, b, c + 1, (openMask >> 1) | 2);
        } else {
            res += solve(pos + 1, a, b, c + 1, ((openMask ^ 4) >> 1) | 2);
        }

        res %= MOD;
        dp[pos][a][b][c][openMask] = res;
        return res;
    }
}

