        if (dp[a][b][c][mask] != -1) return dp[a][b][c][mask];
        int used = a + b + c;
        int claimed = Integer.bitCount(mask);
        int pos = 2 * used - claimed; // positions processed so far... 
        // Actually let me recount: each pair consumes 2 positions. open pairs consume 1 so far.
        // pos = number of positions fully accounted = 2*(a+b+c) - open_count
        // Hmm, let me just track position explicitly... but it's determined.
        // pos (0-indexed) = a+b+c pairs closed * 2 - but open ones...
        // Let open = bitcount(mask). pos_processed = 2*(a+b+c) - open... no.
        // pos = next position to process (1-indexed)
        // Each closed pair contributes 2 positions, each open pair contributes 1 position so far
        int open = Integer.bitCount(mask);
