public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int A = fs.nextInt();
        int B = fs.nextInt();
        int C = fs.nextInt();

        // DP over positions 1..2N.
        // At step i, we decide how to use number i.
        // Since max pair length is 3, only connections to i+1, i+2, i+3 matter.
        // State is:
        // mask over next 3 positions (i, i+1, i+2 relative to current window after shifting),
        // and used counts of diff1 and diff2. diff3 is determined by processed pairs count.
        //
        // More concretely before processing position pos, mask bit 0 means pos is already occupied
        // by a pair started earlier, bit 1 means pos+1 occupied, bit 2 means pos+2 occupied.
        //
        // If bit0=1, pos is already matched; we just advance.
        // Else we must start a pair at pos with pos+1 / pos+2 / pos+3 if available and not occupied.

        int maxPos = 2 * N;
        int states = 8;
        long[][][] dp = new long[A + 1][B + 1][states];
        dp[0][0][0] = 1;

        for (int pos = 1; pos <= maxPos; pos++) {
            long[][][] ndp = new long[A + 1][B + 1][states];
            for (int a = 0; a <= A; a++) {
                for (int b = 0; b <= B; b++) {
                    for (int mask = 0; mask < 8; mask++) {
                        long cur = dp[a][b][mask];
                        if (cur == 0) continue;

                        if ((mask & 1) != 0) {
                            // pos already matched, shift window
                            int nmask = mask >> 1;
                            ndp[a][b][nmask] += cur;
                            if (ndp[a][b][nmask] >= MOD) ndp[a][b][nmask] -= MOD;
                        } else {
                            // Need to pair pos with pos+d, d=1..3
                            // d=1 => target is pos+1, corresponding to bit1 in current mask
                            if (pos + 1 <= maxPos && (mask & 2) == 0 && a < A) {
                                int nmask = (mask | 2) >> 1;
                                ndp[a + 1][b][nmask] += cur;
                                if (ndp[a + 1][b][nmask] >= MOD) ndp[a + 1][b][nmask] -= MOD;
                            }
                            // d=2 => target is pos+2, corresponding to bit2
                            if (pos + 2 <= maxPos && (mask & 4) == 0 && b < B) {
                                int nmask = (mask | 4) >> 1;
                                ndp[a][b + 1][nmask] += cur;
                                if (ndp[a][b + 1][nmask] >= MOD) ndp[a][b + 1][nmask] -= MOD;
                            }
                            // d=3 => target is pos+3, outside current mask; after shift it becomes bit2
                            int usedPairsSoFar = (pos - 1) / 2; // not directly usable
                            // We don't track C explicitly here; only ensure total counts at end.
                            // For d=3, just place occupancy at future position pos+3 if within range.
                            if (pos + 3 <= maxPos) {
                                int nmask = ((mask | 8) >> 1) & 7; // temporarily use bit3 then shift
                                ndp[a][b][nmask] += cur;
                                if (ndp[a][b][nmask] >= MOD) ndp[a][b][nmask] -= MOD;
                            }
                        }
                    }
                }
            }
            dp = ndp;
        }

        // All positions processed, no pending occupied future positions.
        System.out.println(dp[A][B][0] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

