int main(){
    int N, A, B, C;
    cin >> N >> A >> B >> C;

    int total = 2*N;
    // dp[mask][a][b]: mask = bitmask of next 2 positions being taken
    // We process positions 1..2N
    // State: at position i, mask for {i+1, i+2} already taken

    vector<vector<vector<long long>>> dp(4, vector<vector<long long>>(A+1, vector<long long>(B+1, 0)));
    dp[0][0][0] = 1;

    for(int i = 1; i <= total; i++){
        vector<vector<vector<long long>>> ndp(4, vector<vector<long long>>(A+1, vector<long long>(B+1, 0)));
        for(int mask = 0; mask < 4; mask++){
            for(int a = 0; a <= A; a++){
                for(int b = 0; b <= B; b++){
                    long long val = dp[mask][a][b];
                    if(!val) continue;
                    if(mask & 1){ // position i is taken
                        ndp[mask>>1][a][b] = (ndp[mask>>1][a][b] + val) % MOD;
                    } else { // pair i with i+k
                        for(int k = 1; k <= 3; k++){
                            if(i+k > total) continue;
                            int bit = k-1; // bit for position i+k in extended mask (bits 0,1,2 for i+1,i+2,i+3)
                            if(bit < 2 && (mask>>bit & 1)) continue; // already taken
                            // new mask: remove bit 0 (pos i+1), shift, set bit for i+k
                            int nmask = mask >> 1;
                            if(k == 2) nmask |= 1; // i+2 taken, which is bit 0 in new mask (offset from i+1)
                            if(k == 3) nmask |= 2; // i+3 taken, bit 1
                            int na = a + (k==1), nb = b + (k==2);
                            if(na > A || nb > B) continue;
                            if(k==3 && (a + (k==1)) + (b + (k==2)) + 1 > A+B+C) continue;
                            ndp[nmask][na][nb] = (ndp[nmask][na][nb] + val) % MOD;
                        }
                    }
                }
            }
        }
        dp = ndp;
    }
    cout << dp[0][A][B] << endl;
}

