static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, A, B, C;
    cin >> N >> A >> B >> C;

    // dp over positions 1..2N.
    // State is a 3-bit mask describing which of i+1, i+2, i+3
    // are already reserved by pairs started earlier.
    //
    // We process the smallest not-yet-used number i.
    // Since every pair difference is at most 3, i must be paired with
    // i+1 / i+2 / i+3 if available.
    //
    // dp[pos][a][b][mask]:
    // after processing numbers < pos,
    // used exactly a pairs with diff 1 and b pairs with diff 2,
    // and 'mask' tells which of pos, pos+1, pos+2 are already occupied
    // relative to current pos:
    // bit 0 -> pos is occupied
    // bit 1 -> pos+1 is occupied
    // bit 2 -> pos+2 is occupied
    //
    // We only need rolling arrays over pos.

    vector<vector<array<long long, 8>>> cur(A + 1, vector<array<long long, 8>>(B + 1));
    vector<vector<array<long long, 8>>> nxt(A + 1, vector<array<long long, 8>>(B + 1));

    cur[0][0][0] = 1;

    for (int pos = 1; pos <= 2 * N; pos++) {
        for (int a = 0; a <= A; a++) {
            for (int b = 0; b <= B; b++) {
                for (int m = 0; m < 8; m++) nxt[a][b][m] = 0;
            }
        }

        for (int a = 0; a <= A; a++) {
            for (int b = 0; b <= B; b++) {
                for (int mask = 0; mask < 8; mask++) {
                    long long ways = cur[a][b][mask];
                    if (!ways) continue;

                    if (mask & 1) {
                        // pos is already used, just advance.
                        int nmask = mask >> 1;
                        nxt[a][b][nmask] = (nxt[a][b][nmask] + ways) % MOD;
                    } else {
                        // pos is free; it must start a pair with pos+1, pos+2, or pos+3.
                        // diff = 1
                        if (a < A && !(mask & 2) && pos + 1 <= 2 * N) {
                            int nmask = (mask | 2) >> 1;
                            nxt[a + 1][b][nmask] = (nxt[a + 1][b][nmask] + ways) % MOD;
                        }
                        // diff = 2
                        if (b < B && !(mask & 4) && pos + 2 <= 2 * N) {
                            int nmask = (mask | 4) >> 1;
                            nxt[a][b + 1][nmask] = (nxt[a][b + 1][nmask] + ways) % MOD;
                        }
                        // diff = 3
                        int c_used = (pos - 1) / 2 - a - b; // processed pairs so far among numbers < pos
                        // More simply, we can just check final count by not exceeding C.
                        // Number of started pairs so far equals (pos-1 - popcount(mask&1? doesn't matter))/2 is messy.
                        // Easier: since all pairs are determined by transitions, just allow diff=3
                        // whenever within bounds; counts of A and B fixed, and total pairs is N,
                        // so number of diff=3 pairs will automatically be C at the end.
                        if (pos + 3 <= 2 * N) {
                            // Reserve pos+3. It is outside current 3-bit window, so after shifting
                            // it becomes bit 2 in next mask.
                            int nmask = (mask >> 1) | 4;
                            nxt[a][b][nmask] = (nxt[a][b][nmask] + ways) % MOD;
                        }
                    }
                }
            }
        }

        cur.swap(nxt);
    }

    cout << cur[A][B][0] % MOD << '\n';
    return 0;
}

