                int cur = dp[pos][a][mask];
                if (cur == 0) continue;

                // Check if current position is already taken
                if (mask & 1) {
                    // Already paired, move to next with mask shifted
                    int newmask = (mask >> 1);
                    dp[pos+1][a][newmask] = (dp[pos+1][a][newmask] + cur) % MOD;
                    continue;
                }

                // Try pairing with pos+1 (diff=1)
