                    int newmask = (mask >> 1) | (1 << 1); // pos+2 gets shifted into bit0, but we mark pos+1 as taken now => in shifted view, it's bit0 set? careful
                    // Actually simpler: pair pos with pos+1, mark pos+1 used: next mask bits: originally mask bits for pos+1, pos+2, pos+3.
                    // After moving to pos+1, new mask bits for pos+2, pos+3, pos+4.
                    // pos+1 was bit1 (value 2). After shift, bit0 of newmask corresponds to pos+2's status.
                    // So we set bit0=1 in newmask if pos+2 was already taken? Wait careful.
                    // Let's recompute cleanly:

                    // At pos: mask bits: bit0=pos+1 used, bit1=pos+2 used, bit2=pos+3 used.
                    // We are at pos, not used, pair with pos+1:
                    // Then at pos+1: we need mask for pos+2, pos+3, pos+4.
                    // - pos+2 used if originally bit1 was set OR if we just paired pos with pos+1? No, pos+2 not affected.
                    // - pos+3 used if bit2 was set.
                    // - pos+4 is always free.
                    // So newmask = ((mask >> 2) << 1) | ((mask>>1)&1)?? Let's just do: newmask = ((mask & 4) ? 2 : 0) | ((mask & 2) ? 1 : 0);
                    int newmask = ((mask & 4) ? 2 : 0) | ((mask & 2) ? 1 : 0);
                    dp[pos+1][a+1][newmask] = (dp[pos+1][a+1][newmask] + cur) % MOD;
                }

                // Try pairing with pos+2 (diff=2)
                if (b < B && pos+2 <= total && !(mask & 4)) {
                    // pos+2 is bit2 in mask
                    // Pair pos with pos+2: 
                    // At pos+1: newmask for pos+2,pos+3,pos+4:
                    // pos+2 becomes used (by us), pos+3 used if bit2 was set? Wait bit2 was for pos+3 originally.
                    // Let's define: at pos, mask bits: b0=pos+1, b1=pos+2, b2=pos+3.
                    // We pair pos with pos+2 (b1). At pos+1:
                    // - pos+2 used? YES (by us) -> bit0=1
                    // - pos+3 used? if b2==1 -> bit1=1
                    // - pos+4 used? no -> bit2=0
                    int newmask = 1 | ((mask & 4) ? 2 : 0);
                    dp[pos+1][a][newmask] = (dp[pos+1][a][newmask] + cur) % MOD;
                }

                // Try pairing with pos+3 (diff=3)
                if (c < C && pos+3 <= total) {
                    // pos+3 not tracked in mask, so always possible if within range
                    // At pos+1, mask for pos+2,pos+3,pos+4:
                    // pos+2 used if b1 set? b1=bit1 originally
                    // pos+3 used? YES by us -> bit1=1
                    // pos+4 free
                    int newmask = ((mask & 2) ? 1 : 0) | 2;
                    dp[pos+1][a][newmask] = (dp[pos+1][a][newmask] + cur) % MOD;
                }
            }
        }
    }

    // Answer is dp[total+1][A][0] after processing all positions
    printf("%d\n", dp[total+1][A][0]);
    return 0;
}

