                    // pair i with i+2
                    if(b < B && !(nmask & 2)) ndp[nmask|2][a][b+1][c]=(ndp[nmask|2][a][b+1][c]+v)%MOD;
                    // pair i with i+3
                    if(c < C && !(nmask & 4)) ndp[nmask|4][a][b][c+1]=(ndp[nmask|4][a][b][c+1]+v)%MOD;
                }
            }
        }
        memcpy(dp, ndp, sizeof(dp));
    }
    printf("%lld\n", dp[0][A][B][C]);
}

#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N, A, B, C;
    if (scanf("%d %d %d %d", &N, &A, &B, &C) != 4) return 0;

    int M = 2 * N;

    /* dp[i][mask][a][b]:
       processed positions 1..i
       mask = occupancy status of i+1, i+2, i+3 (bit 0,1,2)
       used exactly a pairs with diff 1, b pairs with diff 2
       diff 3 count is implied by total pairs formed so far
    */
    int maxA = A, maxB = B;

    int states = 8 * (maxA + 1) * (maxB + 1);
    long long *dp = (long long *)calloc(states, sizeof(long long));
    long long *ndp = (long long *)calloc(states, sizeof(long long));
    if (!dp || !ndp) return 0;

    #define IDX(mask,a,b) ((((mask) * (maxA + 1)) + (a)) * (maxB + 1) + (b))

    dp[IDX(0, 0, 0)] = 1;

    for (int i = 1; i <= M; i++) {
        for (int t = 0; t < states; t++) ndp[t] = 0;

        for (int mask = 0; mask < 8; mask++) {
            for (int a = 0; a <= maxA; a++) {
                for (int b = 0; b <= maxB; b++) {
                    long long cur = dp[IDX(mask, a, b)];
                    if (!cur) continue;

                    int occupied = mask & 1;
                    int nextmask_base = mask >> 1; /* statuses for i+2, i+3 become bits 0,1 */

                    if (occupied) {
                        /* i is already matched from earlier */
                        ndp[IDX(nextmask_base, a, b)] += cur;
                        if (ndp[IDX(nextmask_base, a, b)] >= MOD) ndp[IDX(nextmask_base, a, b)] -= MOD;
                    } else {
                        /* i must be matched with i+1, i+2, or i+3 if available */
                        /* diff 1: partner i+1 -> current bit1 in old mask must be 0 */
                        if ((mask & 2) == 0 && a + 1 <= maxA) {
                            int nmask = nextmask_base | 1; /* old bit1 becomes current after shift, mark occupied */
                            ndp[IDX(nmask, a + 1, b)] += cur;
                            if (ndp[IDX(nmask, a + 1, b)] >= MOD) ndp[IDX(nmask, a + 1, b)] -= MOD;
                        }
                        /* diff 2: partner i+2 -> old bit2 must be 0 */
                        if ((mask & 4) == 0 && b + 1 <= maxB) {
                            int nmask = nextmask_base | 2; /* after shift, old bit2 becomes bit1 */
                            ndp[IDX(nmask, a, b + 1)] += cur;
                            if (ndp[IDX(nmask, a, b + 1)] >= MOD) ndp[IDX(nmask, a, b + 1)] -= MOD;
                        }
                        /* diff 3: partner i+3, always within lookahead mask as new bit2 after shift */
                        int pairs_done_before = (i - 1 - __builtin_popcount((unsigned)mask)) / 2;
                        int c_used = pairs_done_before - a - b;
                        if (c_used + 1 <= C) {
                            int nmask = nextmask_base | 4;
                            ndp[IDX(nmask, a, b)] += cur;
                            if (ndp[IDX(nmask, a, b)] >= MOD) ndp[IDX(nmask, a, b)] -= MOD;
                        }
                    }
                }
            }
        }

        long long *tmp = dp;
        dp = ndp;
        ndp = tmp;
    }

    printf("%lld\n", dp[IDX(0, A, B)] % MOD);

    free(dp);
    free(ndp);
    return 0;
}

MOD = 10**9 + 7

def solve():
    N, A, B, C = map(int, input().split())
    # dp[i][a][b][c] but compressed: we only need last few states
    # We process positions 1..2N
    # Maintain mask of next 3 positions' availability
    # Also track counts of remaining pairs of each type

    from functools import lru_cache

    @lru_cache(None)
    def dfs(pos, mask, a, b, c):
        if pos > 2 * N:
            return 1 if a == 0 and b == 0 and c == 0 else 0
        if mask & 1:
            # already paired
            return dfs(pos + 1, mask >> 1, a, b, c)
        res = 0
        # try diff 1
        if a > 0 and pos + 1 <= 2 * N and not (mask & 2):
            res += dfs(pos + 1, (mask >> 1) | 1, a - 1, b, c)
        # try diff 2
        if b > 0 and pos + 2 <= 2 * N and not (mask & 4):
            res += dfs(pos + 1, (mask >> 1) | 2, a, b - 1, c)
        # try diff 3
        if c > 0 and pos + 3 <= 2 * N and not (mask & 8):
            res += dfs(pos + 1, (mask >> 1) | 4, a, b, c - 1)
        return res % MOD

    print(dfs(1, 0, A, B, C) % MOD)

if __name__ == "__main__":
    solve()
